COMMIT;

-- ----------------------------
-- Table structure for interview
-- ----------------------------
DROP TABLE IF EXISTS `interview`;
CREATE TABLE `interview` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(255) DEFAULT NULL COMMENT '面试标题',
  `description` varchar(1024) DEFAULT NULL COMMENT '描述',
  `type` varchar(255) DEFAULT NULL COMMENT '面试类型，包括专项面、深度面、简历普通面',
  `extend_content` varchar(1024) DEFAULT NULL COMMENT '拓展字段',
  `profile` varchar(524) DEFAULT NULL COMMENT '用户求职画像',
  `account_id` bigint DEFAULT NULL COMMENT '账号ID',
  `resume_id` bigint DEFAULT NULL COMMENT '简历ID',
  `status` varchar(64) DEFAULT NULL COMMENT '面试状态：GENERATING、IN_PROGRESS、EVALUATING',
  `overall_score` decimal(16,2) DEFAULT NULL COMMENT '总体评分（0-100分）',
  `summary` varchar(2048) DEFAULT NULL COMMENT '面试总结和评价',
  `strength` varchar(1024) DEFAULT NULL COMMENT '优势分析',
  `improvement` varchar(1024) DEFAULT NULL COMMENT '需要改进的地方',
  `suggestion` varchar(1024) DEFAULT NULL COMMENT '具体建议',
  `technical_skills` decimal(16,2) DEFAULT NULL COMMENT '技术能力评分',
  `logical_thinking` decimal(16,2) DEFAULT NULL COMMENT '逻辑思维评分',
  `communication` decimal(16,2) DEFAULT NULL COMMENT '表达能力评分',
  `problem_solving` decimal(16,2) DEFAULT NULL COMMENT '解决问题能力评分',
  `passed_question` int DEFAULT NULL COMMENT '及格题目数（>=60分）',
  `excellent_question` int DEFAULT NULL COMMENT '优秀题目数（>=80分）',
  `gmt_create` datetime DEFAULT CURRENT_TIMESTAMP,
  `gmt_modified` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=251 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------
-- Records of interview
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for interview_round
-- ----------------------------
DROP TABLE IF EXISTS `interview_round`;
CREATE TABLE `interview_round` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `interview_id` bigint NOT NULL,
  `account_id` bigint DEFAULT NULL,
  `round_number` int DEFAULT NULL COMMENT '第几轮面试',
  `round_type` varchar(50) NOT NULL COMMENT '本轮面试类型',
  `status` varchar(64) DEFAULT NULL COMMENT '面试状态：IN_PROGRESS、EVALUATING、COMPLETED',
  `description` varchar(2048) DEFAULT NULL COMMENT '本轮面试的主要考察内容',
  `total_question` int DEFAULT '0' COMMENT '面试总题目数量',
  `answered_questions` int DEFAULT '0' COMMENT '已经回答的题目',
  `overall_score` decimal(16,2) DEFAULT NULL COMMENT '总体评分',
  `summary` varchar(2048) DEFAULT NULL COMMENT '面试总结和评价',
  `strength` varchar(2048) DEFAULT NULL COMMENT '优势分析',
  `improvement` varchar(2048) DEFAULT NULL COMMENT '需要改进的地方',
  `suggestion` varchar(2048) DEFAULT NULL COMMENT '具体建议',
  `gmt_modified` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `gmt_create` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=755 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------
-- Records of interview_round
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for question
-- ----------------------------
DROP TABLE IF EXISTS `question`;
CREATE TABLE `question` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `interview_id` bigint DEFAULT NULL COMMENT '面试轮次ID',
  `account_id` bigint DEFAULT NULL,
  `interview_round_id` bigint DEFAULT NULL COMMENT '轮次ID',
  `status` varchar(255) DEFAULT NULL COMMENT '状态',
  `user_answer` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '用户答案',
  `evaluation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '题目点评',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '题目内容',
  `type` varchar(255) DEFAULT NULL COMMENT 'CODING、SHORT_ANSWER',
  `difficulty` varchar(255) DEFAULT NULL COMMENT 'BEGINNER、INTERMEDIATE、ADVANCED',
  `category` varchar(255) DEFAULT NULL COMMENT '题目分类（如：Java基础、Spring框架、数据库等）',
  `standard_answer` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '标准答案',
  `key_points` varchar(510) DEFAULT NULL COMMENT '关键要点，JSON格式',
  `max_score` int DEFAULT '100' COMMENT '满分分值100',
  `time_limit` int DEFAULT NULL COMMENT '答题时间限制（分钟）',
  `user_score` int DEFAULT NULL COMMENT '回答评分',
  `gmt_create` datetime DEFAULT CURRENT_TIMESTAMP,
  `gmt_modified` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2838 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

